1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"strings"
9	
10		"github.com/go-git/go-git/v6/plumbing"
11		"github.com/spf13/cobra"
12	
13		"github.com/entireio/cli/cmd/entire/cli/checkpoint"
14		"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
15		"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
16		"github.com/entireio/cli/cmd/entire/cli/gitremote"
17		"github.com/entireio/cli/internal/coreapi"
18	)
19	
20	// explainRepoRef is a parsed `explain --repo` value: either an owner/name slug
21	// (possibly given with a gh/ prefix) or a raw repo ULID that still needs a
22	// control-plane lookup to become owner/name.
23	type explainRepoRef struct {
24		owner, repo string // owner/name form (lowercased)
25		repoID      string // bare-ULID form
26	}
27	
28	// parseExplainRepoFlag parses the --repo flag value. Accepted shapes:
29	// `owner/name`, `gh/owner/name` (leading slash optional), or a bare repo ULID.
30	// owner/name reuse the GitHub charset validation of the mirror clone-ref
31	// parser and come back lowercased, matching what the control plane persists.
32	func parseExplainRepoFlag(value string) (explainRepoRef, error) {
33		v := strings.TrimSpace(value)
34		if v == "" {
35			return explainRepoRef{}, errors.New("--repo requires a value: owner/name, gh/owner/name, or a repo ID")
36		}
37		if strings.Contains(v, "/") {
38			// Normalize owner/name to the gh/owner/name clone-ref shape so
39			// parseMirrorCloneRef's charset validation applies to both forms.
40			ref := strings.TrimPrefix(v, "/")
41			if !strings.HasPrefix(ref, "gh/") {
42				ref = "gh/" + ref
43			}
44			_, owner, repo, err := parseMirrorCloneRef(ref)
45			if err != nil {
46				return explainRepoRef{}, fmt.Errorf("invalid --repo %q: expected owner/name, gh/owner/name, or a repo ID: %w", value, err)
47			}
48			return explainRepoRef{owner: owner, repo: repo}, nil
49		}
50		if !looksLikeULID(v) {
51			return explainRepoRef{}, fmt.Errorf("invalid --repo %q: expected owner/name, gh/owner/name, or a repo ID (ULID)", value)
52		}
53		return explainRepoRef{repoID: v}, nil
54	}
55	
56	// resolveExplainRepoID resolves a raw repo ULID to its owner/name via the
57	// control plane's by-id lookup (the same call `entire repo get <ulid>` uses).
58	// A clusterFlag naming a cluster in a different federation dials that
59	// cluster's core instead of the active context's, matching how the placement
60	// lookup routes (see listPullablePlacements).
61	func resolveExplainRepoID(cmd *cobra.Command, repoID, clusterFlag string) (owner, repo string, err error) {
62		runWithCore, err := coreRunnerForCluster(clusterFlag)
63		if err != nil {
64			return "", "", err
65		}
66		var fullName string
67		err = runWithCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
68			r, err := c.GetRepo(ctx, coreapi.GetRepoParams{RepoId: repoID})
69			if err != nil {
70				if isCoreNotFound(err) {
71					return fmt.Errorf("no repository with ID %q visible from your login", repoID)
72				}
73				return fmt.Errorf("look up repository %q: %w", repoID, err)
74			}
75			fullName = r.FullName.Or("")
76			return nil
77		})
78		if err != nil {
79			return "", "", err
80		}
81		owner, repo, ok := strings.Cut(strings.ToLower(fullName), "/")
82		if !ok || owner == "" || repo == "" {
83			return "", "", fmt.Errorf("repository %q has an unexpected full name %q (want owner/name)", repoID, fullName)
84		}
85		return owner, repo, nil
86	}
87	
88	// explainRepoIsCurrent reports whether owner/repo names the same repository as
89	// the cwd worktree's origin remote (handles ssh, https, and entire:// mirror
90	// URL forms). --repo is GitHub-scoped (gh/owner/name), so a non-GitHub origin
91	// with a coincidentally matching owner/name must not count as the current
92	// repo. Best-effort: any lookup or parse failure returns false, so explain
93	// proceeds with the cross-repo fetch path.
94	func explainRepoIsCurrent(ctx context.Context, owner, repo string) bool {
95		curForge, curOwner, curRepo, err := gitremote.ResolveRemoteRepo(ctx, "origin")
96		if err != nil || curForge != "gh" {
97			return false
98		}
99		return strings.EqualFold(curOwner, owner) && strings.EqualFold(curRepo, repo)
100	}
101	
102	// resolveExplainRepoFetchURL resolves the entire:// mirror URL to fetch a
103	// foreign repo's checkpoint ref from: pullable placements via the core API
104	// (the same authority `repo clone` uses), then the shared placement picker
105	// with explain-specific wording and the --cluster escape hatch.
106	func resolveExplainRepoFetchURL(cmd *cobra.Command, owner, repo, clusterFlag string) (string, error) {
107		placements, err := listPullablePlacements(cmd, owner, repo, clusterFlag)
108		if err != nil {
109			return "", err
110		}
111		if len(placements) == 0 {
112			return "", fmt.Errorf("no mirror found for /gh/%s/%s; cross-repo explain fetches checkpoints from the repo's Entire mirror", owner, repo)
113		}
114		chosen, err := selectPlacement(cmd, placements, clusterFlag, placementPicker{
115			selector: "--cluster",
116			title:    "This repo is mirrored on more than one cluster — pick one to fetch the checkpoint from",
117			action:   "Explain",
118		})
119		if err != nil {
120			return "", err
121		}
122		// chosen.ClusterHost is server-provided but interpolated into the entire://
123		// URL like a user-supplied --cluster, so apply the same anti-token-leak
124		// guard before building it (see repo clone).
125		if err := validateClusterHost(chosen.ClusterHost); err != nil {
126			return "", fmt.Errorf("mirror has an invalid cluster host %q: %w", chosen.ClusterHost, err)
127		}
128		return mirrorCloneURL(chosen.ClusterHost, owner, repo), nil
129	}
130	
131	// prepareCrossRepoExplain resolves --repo/--cluster and, when the target repo
132	// differs from the cwd repo, fetches the checkpoint's per-checkpoint ref from
133	// that repo's Entire mirror into the cwd repo's object store. After a nil
134	// return, the normal explain flow resolves the checkpoint as if it were local.
135	// When --repo names the cwd repo it is a no-op (behavior identical to no flag).
